-- Insert Quiz Questions for Lesson: Configure Registration and Public Pages

DO $$
DECLARE
  v_module_id UUID;
  v_lesson_id UUID;
  v_quiz_id UUID;
BEGIN
  -- Get Module by week number
  SELECT id INTO v_module_id FROM public.training_modules WHERE week_number = 18 LIMIT 1;
  
  IF v_module_id IS NULL THEN
    RAISE NOTICE 'Module 18 not found';
    RETURN;
  END IF;

  -- Get the lesson ID
  SELECT id INTO v_lesson_id 
  FROM public.lessons 
  WHERE slug = 'configure-registration-public-pages' AND module_id = v_module_id;
  
  IF v_lesson_id IS NULL THEN
    RAISE NOTICE 'Lesson configure-registration-public-pages not found in module 18';
    RETURN;
  END IF;
  
  -- Delete existing quizzes to avoid duplicates
  DELETE FROM public.lesson_quizzes WHERE lesson_id = v_lesson_id;


  -- Question 1
  INSERT INTO public.lesson_quizzes (lesson_id, question, options, correct_answer, explanation, sort_order)
  VALUES (
    v_lesson_id, 
    'What does a capacity setting of 0 mean?', 
    '["No one can register","Only admins can register","Unlimited total registrations","Registration is closed"]'::jsonb,
    'Unlimited total registrations',
    'According to HighLevel, a capacity setting of 0 means unlimited total registrations.', 
    1
  )
  RETURNING id INTO v_quiz_id;


  -- Question 2
  INSERT INTO public.lesson_quizzes (lesson_id, question, options, correct_answer, explanation, sort_order)
  VALUES (
    v_lesson_id, 
    'Which fields are required on the registration form?', 
    '["First name, last name, email, and phone number","First name, last name, and email only","Email and company name only","All fields are optional"]'::jsonb,
    'First name, last name, and email only',
    'First name, last name, and email are required. Add other fields only when you genuinely need them.', 
    2
  )
  RETURNING id INTO v_quiz_id;


  -- Question 3
  INSERT INTO public.lesson_quizzes (lesson_id, question, options, correct_answer, explanation, sort_order)
  VALUES (
    v_lesson_id, 
    'What should you do before sending invitations to a Ticketed event?', 
    '["Turn on Live mode immediately","Test the checkout flow and confirm Live mode is OFF for testing","Delete all test registrations","Set capacity to 0"]'::jsonb,
    'Test the checkout flow and confirm Live mode is OFF for testing',
    'For Ticketed events, test the checkout flow and confirm Live mode is OFF before testing. Never process real test payments.', 
    3
  )
  RETURNING id INTO v_quiz_id;

END $$;
