-- Insert Quiz Questions for Lesson: Publish and Promote

DO $$
DECLARE
  v_module_id UUID;
  v_lesson_id UUID;
  v_quiz_id UUID;
BEGIN
  -- Get Module by week number
  SELECT id INTO v_module_id FROM public.training_modules WHERE week_number = 18 LIMIT 1;
  
  IF v_module_id IS NULL THEN
    RAISE NOTICE 'Module 18 not found';
    RETURN;
  END IF;

  -- Get the lesson ID
  SELECT id INTO v_lesson_id 
  FROM public.lessons 
  WHERE slug = 'publish-and-promote' AND module_id = v_module_id;
  
  IF v_lesson_id IS NULL THEN
    RAISE NOTICE 'Lesson publish-and-promote not found in module 18';
    RETURN;
  END IF;
  
  -- Delete existing quizzes to avoid duplicates
  DELETE FROM public.lesson_quizzes WHERE lesson_id = v_lesson_id;


  -- Question 1
  INSERT INTO public.lesson_quizzes (lesson_id, question, options, correct_answer, explanation, sort_order)
  VALUES (
    v_lesson_id, 
    'When should you publish your event?', 
    '["Immediately after creating the draft","Only when the event is real and ready to accept registrations","After 24 hours in draft status","When you have at least 5 registrants"]'::jsonb,
    'Only when the event is real and ready to accept registrations',
    'Publish only when the event is real and ready. For practice events, keep as Draft and record a screenshot.', 
    1
  )
  RETURNING id INTO v_quiz_id;


  -- Question 2
  INSERT INTO public.lesson_quizzes (lesson_id, question, options, correct_answer, explanation, sort_order)
  VALUES (
    v_lesson_id, 
    'Where can you find the embed code for your event?', 
    '["Memberships → Events → Design","Settings → Link & Tracking","Marketing → Funnels","Contacts → Forms"]'::jsonb,
    'Settings → Link & Tracking',
    'The embed code is found under Settings → Link & Tracking, allowing you to add registration to an existing website or funnel.', 
    2
  )
  RETURNING id INTO v_quiz_id;


  -- Question 3
  INSERT INTO public.lesson_quizzes (lesson_id, question, options, correct_answer, explanation, sort_order)
  VALUES (
    v_lesson_id, 
    'What three questions must your invitation answer?', 
    '["Who, What, Where","What is the event, Why should I attend, How do I register","When, Where, How much","Who is speaking, What is the topic, Where is it located"]'::jsonb,
    'What is the event, Why should I attend, How do I register',
    'Every invitation must clearly answer: What is the event? Why should I attend? How do I register?', 
    3
  )
  RETURNING id INTO v_quiz_id;

END $$;
