  v_quiz_id UUID;
BEGIN
  -- Get Module by week number
  SELECT id INTO v_module_id FROM public.training_modules WHERE week_number = 18 LIMIT 1;
  
  IF v_module_id IS NULL THEN
    RAISE NOTICE 'Module 18 not found';
    RETURN;
  END IF;

  -- Get the lesson ID
  SELECT id INTO v_lesson_id 
  FROM public.lessons 
  WHERE slug = 'manage-attendees-follow-up' AND module_id = v_module_id;
  
  IF v_lesson_id IS NULL THEN
    RAISE NOTICE 'Lesson manage-attendees-follow-up not found in module 18';
    RETURN;
  END IF;
  
  -- Delete existing quizzes to avoid duplicates
  DELETE FROM public.lesson_quizzes WHERE lesson_id = v_lesson_id;


  -- Question 1
  INSERT INTO public.lesson_quizzes (lesson_id, question, options, correct_answer, explanation, sort_order)
  VALUES (
    v_lesson_id, 
    'Which tab shows event registrants?', 
    '["Settings","Pages & Design","Registrations","Analytics"]'::jsonb,
    'Registrations',
    'The Registrations tab shows all event registrants and their registration status.', 
    1
  )
  RETURNING id INTO v_quiz_id;


  -- Question 2
  INSERT INTO public.lesson_quizzes (lesson_id, question, options, correct_answer, explanation, sort_order)
  VALUES (
    v_lesson_id, 
    'Why should you collect actual attendance data before sending follow-ups?', 
    '["Because registration data is automatically deleted after the event","Because registration alone does not prove attendance, and inaccurate segments lead to inappropriate messages","Because HighLevel requires attendance verification for all events","Because follow-up emails are only sent to attendees"]'::jsonb,
    'Because registration alone does not prove attendance, and inaccurate segments lead to inappropriate messages',
    'Registration alone does not prove a webinar attendee joined. Use reliable attendance records to avoid sending inappropriate messages.', 
    2
  )
  RETURNING id INTO v_quiz_id;


  -- Question 3
  INSERT INTO public.lesson_quizzes (lesson_id, question, options, correct_answer, explanation, sort_order)
  VALUES (
    v_lesson_id, 
    'What should your post-event follow-up include?', 
    '["A request to register for the same event again","A thank-you, main takeaway, and clear next step linked to your business goal","A discount code for unrelated products","A survey with 20 questions"]'::jsonb,
    'A thank-you, main takeaway, and clear next step linked to your business goal',
