-- Insert Quiz Questions for Lesson: Advanced Options

DO $$
DECLARE
  v_module_id UUID;
  v_lesson_id UUID;
  v_quiz_id UUID;
BEGIN
  -- Get Module by week number
  SELECT id INTO v_module_id FROM public.training_modules WHERE week_number = 18 LIMIT 1;
  
  IF v_module_id IS NULL THEN
    RAISE NOTICE 'Module 18 not found';
    RETURN;
  END IF;

  -- Get the lesson ID
  SELECT id INTO v_lesson_id 
  FROM public.lessons 
  WHERE slug = 'advanced-options' AND module_id = v_module_id;
  
  IF v_lesson_id IS NULL THEN
    RAISE NOTICE 'Lesson advanced-options not found in module 18';
    RETURN;
  END IF;
  
  -- Delete existing quizzes to avoid duplicates
  DELETE FROM public.lesson_quizzes WHERE lesson_id = v_lesson_id;


  -- Question 1
  INSERT INTO public.lesson_quizzes (lesson_id, question, options, correct_answer, explanation, sort_order)
  VALUES (
    v_lesson_id, 
    'Which of these is an advanced Events feature?', 
    '["Creating a contact record","Ticketed registration with tiered pricing","Sending a one-to-one email","Adding a phone number to a contact"]'::jsonb,
    'Ticketed registration with tiered pricing',
    'Ticketed registration with tiered pricing is an advanced feature that allows multiple ticket types at different price points.', 
    1
  )
  RETURNING id INTO v_quiz_id;


  -- Question 2
  INSERT INTO public.lesson_quizzes (lesson_id, question, options, correct_answer, explanation, sort_order)
  VALUES (
    v_lesson_id, 
    'What should you do before adding advanced features?', 
    '["Add every available feature to impress attendees","Pick one sensible addition that serves your attendees or supports your business goal","Upgrade to the highest plan level","Hire a developer to customise the event page"]'::jsonb,
    'Pick one sensible addition that serves your attendees or supports your business goal',
    'Avoid unnecessary complexity. Choose one advanced feature that directly helps attendees or supports your business goal.', 
    2
  )
  RETURNING id INTO v_quiz_id;


  -- Question 3
  INSERT INTO public.lesson_quizzes (lesson_id, question, options, correct_answer, explanation, sort_order)
  VALUES (
    v_lesson_id, 
    'Where can you find Events-related Workflow triggers?', 
    '["Memberships → Events → Settings","Automation → Workflows","Marketing → Campaigns","Contacts → Tags"]'::jsonb,
    'Automation → Workflows',
    'Events-related Workflow triggers and actions are found in Automation → Workflows, subject to supported Events integrations.', 
    3
  )
  RETURNING id INTO v_quiz_id;

END $$;
